import json
from pathlib import Path

from dotenv import load_dotenv

load_dotenv()
from ragas import EvaluationDataset, evaluate
from ragas.metrics import (
    LLMContextRecall,
    Faithfulness,
    FactualCorrectness,
)

from langchain_openai import ChatOpenAI
from ragas.llms import LangchainLLMWrapper


BASE_DIR = Path(__file__).resolve().parent

RAG_RESULTS_FILE = BASE_DIR / "rag_results.json"


def load_rag_results():
    """Load the results generated by our RAG pipeline."""

    with open(RAG_RESULTS_FILE, "r", encoding="utf-8") as f:
        return json.load(f)


def build_evaluation_dataset(results):
    """
    Convert our rag_results.json into the format expected by RAGAS.
    """

    rows = []

    for item in results:

        rows.append(
    {
        "user_input": item["user_input"],
        "retrieved_contexts": item["retrieved_contexts"],
        "response": item["response"],
        "reference": item["reference"],
    }
)

    return EvaluationDataset.from_list(rows)


def main():

    print("=" * 80)
    print("RAGAS EVALUATION")
    print("=" * 80)

    # ---------------------------------------------------------
    # 1. Load RAG results
    # ---------------------------------------------------------

    print("\nLoading RAG results...")

    results = load_rag_results()

    print(f"Loaded {len(results)} evaluation samples.")

    # ---------------------------------------------------------
    # 2. Convert to RAGAS dataset
    # ---------------------------------------------------------

    evaluation_dataset = build_evaluation_dataset(results)

    print("RAGAS dataset created.")

    # ---------------------------------------------------------
    # 3. Create evaluator LLM
    # ---------------------------------------------------------

    print("\nCreating evaluator LLM...")

    evaluator_llm = ChatOpenAI(
        model="gpt-4o-mini",
        temperature=0,
    )

    evaluator_llm = LangchainLLMWrapper(evaluator_llm)

    print("Evaluator LLM ready.")

    # ---------------------------------------------------------
    # 4. Define metrics
    # ---------------------------------------------------------

    metrics = [
        LLMContextRecall(),
        Faithfulness(),
        FactualCorrectness(),
    ]

    print("\nMetrics:")
    print("- Context Recall")
    print("- Faithfulness")
    print("- Factual Correctness")

    # ---------------------------------------------------------
    # 5. Run evaluation
    # ---------------------------------------------------------

    print("\nStarting RAGAS evaluation...\n")

    evaluation_result = evaluate(
        dataset=evaluation_dataset,
        metrics=metrics,
        llm=evaluator_llm,
    )

    # ---------------------------------------------------------
    # 6. Display results
    # ---------------------------------------------------------

    print("\n")
    print("=" * 80)
    print("RAGAS RESULTS")
    print("=" * 80)

    print(evaluation_result)

    # ---------------------------------------------------------
    # 7. Convert to dataframe
    # ---------------------------------------------------------

    dataframe = evaluation_result.to_pandas()

    print("\n")
    print("=" * 80)
    print("DETAILED RESULTS")
    print("=" * 80)

    print(dataframe)

    # ---------------------------------------------------------
    # 8. Save results
    # ---------------------------------------------------------

    output_file = BASE_DIR / "ragas_results.csv"

    dataframe.to_csv(
        output_file,
        index=False,
    )

    print("\n")
    print(f"Results saved to: {output_file}")


if __name__ == "__main__":
    main()